import os, re

def load_grids():
    """Load all grids from session file"""
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    if not session_dir:
        return {}

    session_file = session_dir + '/../../sessions/' + os.path.basename(session_dir) + '.jsonl'
    if not os.path.exists(session_file):
        return {}

    content = open(session_file).read()
    grids = {}

    # Find all demo pairs and test input
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\s*\n([\s\S]*?)(?=\n\n|\nDemo |\nTest input|$)'

    for match in re.finditer(pattern, content):
        key_type = match.group(1)
        h, w = int(match.group(2)), int(match.group(3))
        rows = match.group(4).split('\n')[:h]
        grid = [[int(x) for x in row.split()] for row in rows if row.strip()]

        # Create a unique key
        if 'input' in key_type.lower():
            k = f"input_{h}x{w}"
        elif 'output' in key_type.lower():
            k = f"output_{h}x{w}"
        else:  # Test input
            k = "test_input"

        grids[k] = grid
        print(f"Loaded: {k} ({h}x{w}): {grid[:3]}..." if h > 3 else f"Loaded: {k} ({h}x{w}): {grid}")

    return grids

